#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
int main(int argc,char** argv){try{if(argc<2)return 2;for(int f=1;f<argc;++f){auto g=loadGraph(argv[f]);unsigned found=0;for(unsigned i=0;i<g.elements.size();++i)for(auto& a:g.elements[i].attributes){auto name=g.strings.at(a.name);if(name!="settings" && name!="graphEditorState")continue;++found;std::cout<<argv[f]<<" owner="<<i<<" ownerType="<<g.strings.at(g.elements[i].type)<<" attribute="<<name<<" wireType="<<unsigned(a.type);if(a.type==1){auto target=a.values.at(0).reference;std::cout<<" target="<<target;if(target<g.elements.size()){auto& e=g.elements[target];std::cout<<" targetType="<<g.strings.at(e.type)<<" attributes=";for(auto& b:e.attributes)std::cout<<g.strings.at(b.name)<<":"<<unsigned(b.type)<<",";}}std::cout<<"\n";}std::cout<<"elements="<<g.elements.size()<<" matchingAttributes="<<found<<"\n";}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
